# sessions.py
# ─────────────────────────────────────────────────────────────────────────────
# Lightweight session store backed by a single JSON file on disk.
# Tracks recent chat sessions so the frontend sidebar can show "Recent" summaries.
#
# Each session record:
#   {
#     "id"        : str,    # UUID4 generated by the frontend or server
#     "summary"   : str,    # 1-line description (first user question or archived summary)
#     "subject"   : str,    # e.g. "Biology"
#     "timestamp" : str,    # ISO 8601 datetime string
#     "archived"  : bool,   # True once the session has been summarised into long-term memory
#   }
#
# The file is capped at MAX_SESSIONS entries (oldest pruned first).
# ─────────────────────────────────────────────────────────────────────────────

import json
import logging
from datetime import datetime, timezone
from pathlib import Path

from config import SESSIONS_FILE, MAX_SESSIONS

logger = logging.getLogger(__name__)


# ── INTERNAL HELPERS ──────────────────────────────────────────────────────────

def _load() -> list:
    """Read sessions.json and return the list. Returns [] if file doesn't exist yet."""
    path = Path(SESSIONS_FILE)
    if not path.exists():
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError) as e:
        logger.warning(f"sessions.json unreadable ({e}) — starting fresh")
        return []


def _save(sessions: list) -> None:
    """Write the sessions list back to disk, trimming to MAX_SESSIONS."""
    # Keep only the most recent MAX_SESSIONS (newest first after sort)
    trimmed = sessions[:MAX_SESSIONS]
    with open(SESSIONS_FILE, "w", encoding="utf-8") as f:
        json.dump(trimmed, f, indent=2, ensure_ascii=False)


# ── PUBLIC API ────────────────────────────────────────────────────────────────

def get_all_sessions() -> list:
    """
    Return all stored sessions, newest first.
    Called by GET /api/sessions.
    """
    return _load()


def upsert_session(session_id: str, summary: str, subject: str = "Biology") -> dict:
    """
    Create a new session or update the summary of an existing one.
    Called when:
      - A new chat starts (summary = first question, truncated)
      - A session is archived (summary = LLM-compressed bullet summary)

    Returns the upserted session dict.
    """
    sessions   = _load()
    now        = datetime.now(timezone.utc).isoformat()

    # Check if this session_id already exists
    existing = next((s for s in sessions if s["id"] == session_id), None)

    if existing:
        existing["summary"]   = summary
        existing["timestamp"] = now
    else:
        new_session = {
            "id"       : session_id,
            "summary"  : summary[:120],   # cap at 120 chars for the sidebar
            "subject"  : subject,
            "timestamp": now,
            "archived" : False,
        }
        sessions.insert(0, new_session)   # newest at top
        existing = new_session

    _save(sessions)
    logger.info(f"Session upserted: {session_id[:8]}… — '{summary[:60]}'")
    return existing


def mark_archived(session_id: str, summary: str) -> None:
    """
    Update a session with its LLM-generated summary and mark it as archived.
    Called after POST /api/archive completes successfully.
    """
    sessions = _load()
    for s in sessions:
        if s["id"] == session_id:
            s["summary"]   = summary[:120]
            s["archived"]  = True
            s["timestamp"] = datetime.now(timezone.utc).isoformat()
            break
    _save(sessions)
    logger.info(f"Session {session_id[:8]}… marked as archived")


def delete_session(session_id: str) -> bool:
    """
    Remove a session by ID. Returns True if found and deleted, False if not found.
    """
    sessions = _load()
    filtered = [s for s in sessions if s["id"] != session_id]
    if len(filtered) == len(sessions):
        return False
    _save(filtered)
    logger.info(f"Session {session_id[:8]}… deleted")
    return True
